const from = ($json.from || $json.headers?.from || '').toLowerCase();
if (!from.includes('{{SP_SENDER_DOMAIN}}')) return [];
return [{ json: $json }];

// <lib:e164Normalize>
function e164Normalize(raw) {
  if (raw == null) return null;
  const digits = String(raw).replace(/\D/g, '');
  if (digits.length === 10) return '+1' + digits;
  if (digits.length === 11 && digits.startsWith('1')) return '+' + digits;
  return null;
}
// </lib:e164Normalize>
// harness — SP structured-field parse is build-day (frozen defer-list); normalize the parsed phone.
const phoneRaw = $json.phone_raw ?? null;
const phone_e164 = e164Normalize(phoneRaw);
return [{ json: { ...$json, phone_e164, phone_parse_ok: phone_e164 !== null } }];

const crypto = require('crypto');
// <lib:validateTwilioSignature>
function validateTwilioSignature(authToken, url, params, signatureHeader) {
  // Fail closed on any missing required input.
  if (!authToken || !url || !signatureHeader) return false;

  const p = params || {};
  const data =
    url +
    Object.keys(p)
      .sort()
      .map((k) => k + p[k])
      .join('');

  const expected = crypto
    .createHmac('sha1', authToken)
    .update(Buffer.from(data, 'utf-8'))
    .digest('base64');

  // timingSafeEqual throws on length mismatch — guard so a wrong-length sig returns false, not throws.
  const a = Buffer.from(expected, 'utf-8');
  const b = Buffer.from(String(signatureHeader), 'utf-8');
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}
// </lib:validateTwilioSignature>
// NSA: a credential without signature validation is a silent auth-bypass. Fail closed.
const token = $env.TWILIO_AUTH_TOKEN;            // set in n8n env at setup
const sig = $json.headers?.['x-twilio-signature'];
const url = '{{WEBHOOK_PUBLIC_URL}}';            // exact public URL Twilio POSTs to (filled at setup)
const params = $json.body || {};
const from = params.From;
const message_sid = params.MessageSid;
// Fail LOUD (throw -> error workflow -> the owner alert) if the body shape is wrong. A silent
// return [] here would drop EVERY inbound invisibly (a fail-closed DoS nobody would notice).
if (!from || !message_sid) throw new Error('Twilio webhook body shape unexpected (no From/MessageSid) — verify $json.body mapping at build-day');
// message_sid feeds an Airtable filterByFormula downstream; constrain it like the phone guard (NSA).
if (!/^SM[0-9a-f]{32}$/.test(message_sid)) return []; // malformed/forged SID -> silent drop
if (!validateTwilioSignature(token, url, params, sig)) return []; // forged/unsigned -> silent drop
return [{ json: { body: params.Body, from, message_sid } }];

const STOP_WORDS = ["stop","stopall","unsubscribe","cancel","end","quit"];
const START_WORDS = ["start","unstop"];
// <lib:isStop>
function isStop(text) {
  if (!text) return false;
  return STOP_WORDS.includes(String(text).trim().toLowerCase());
}
// </lib:isStop>
// <lib:isStart>
function isStart(text) {
  if (!text) return false;
  return START_WORDS.includes(String(text).trim().toLowerCase());
}
// </lib:isStart>
const text = $json.body || '';
let route = 'continue';
if (isStop(text)) route = 'stop';
else if (isStart(text)) route = 'start';
return [{ json: { ...$json, route } }];

// <lib:crisisScreen>
function crisisScreen(text) {
  if (!text) return false;
  const t = String(text).toLowerCase();
  const patterns = [
    /\bkill(ing)? (myself|my self)\b/,
    /\bsuicid/,
    /\bend (my life|it all)\b/,
    /\bwan(t to|na) die\b/,
    /\bdon'?t want to (live|be here|exist)\b/,
    /\b(harm|hurt(ing)?) (myself|my self)\b/,
    /\bself[-\s]?harm/,
    /\bcut(ting)? myself\b/,
    /\boverdos/,
    /\btake all (my|the) pills\b/,
    /\bno reason to live\b/,
    /\bbetter off dead\b/,
    /\bnot worth living\b/,
  ];
  return patterns.some((re) => re.test(t));
}
// </lib:crisisScreen>
return [{ json: { ...$json, crisis: crisisScreen($json.body) } }];

// A duplicate => >=1 matched Messages record; first-sight => zero (alwaysOutputData emits one empty item).
const hits = $input.all().map((i) => i.json).filter((r) => r && (r.id || r.fields));
const sig = $('LEG2 · Validate Twilio Signature').first().json;
return [{ json: { seen: hits.length > 0, ...sig } }]; // re-thread {body,from,message_sid} forward

// <lib:e164Normalize>
function e164Normalize(raw) {
  if (raw == null) return null;
  const digits = String(raw).replace(/\D/g, '');
  if (digits.length === 10) return '+1' + digits;
  if (digits.length === 11 && digits.startsWith('1')) return '+' + digits;
  return null;
}
// </lib:e164Normalize>
// phone is a lookup KEY only; guard the normalized value before any Airtable filter.
// NOTE: the upstream Auto-Ack (Twilio) node REPLACED the item, so $json.from here would be the
// Twilio sender, NOT the prospect. Source 'from' from the canonical signature node by name.
const from = $('LEG2 · Validate Twilio Signature').first().json.from;
const e164 = e164Normalize(from);
if (!/^\+1\d{10}$/.test(e164 || '')) return [{ json: { phone_e164: null, tier: 'none' } }];
return [{ json: { phone_e164: e164, tier: 'lookup' } }];

// Airtable Search emits one item per matched record (alwaysOutputData=true => one empty item on zero hits).
const hits = $input.all().map((i) => i.json).filter((r) => r && (r.id || r.fields));
const ctx = $('LEG2 · Match vs Airtable (E.164 exact)').first().json;
const exact = hits.length === 1;
// field path (record.fields.first_name) confirmed against live Airtable output at build-day (defer-list d).
const first_name = exact ? (hits[0].fields?.first_name ?? hits[0].first_name ?? null) : null;
return [{ json: { ...ctx, match_tier: exact ? 'exact' : 'none', first_name } }];

const TONE_BANDS = ["gentle","warm-light"];
// <lib:coerceToneOutput>
function coerceToneOutput(text) {
  const raw = String(text == null ? '' : text).trim();
  let parsed = null;
  try { parsed = JSON.parse(raw); } catch (e) { parsed = null; }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    // Model-swap tolerance: extract the first {...} block from prose-wrapped output.
    const m = raw.match(/\{[\s\S]*?\}/);
    if (m) { try { parsed = JSON.parse(m[0]); } catch (e) { parsed = null; } }
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return { tone_band: 'gentle', crisis_flag: false, parse_ok: false };
  }
  const tone_band = TONE_BANDS.includes(parsed.tone_band) ? parsed.tone_band : 'gentle';
  const crisis_flag = parsed.crisis_flag === true || parsed.crisis_flag === 'true';
  return { tone_band, crisis_flag, parse_ok: true };
}
// </lib:coerceToneOutput>
const out = coerceToneOutput($json.text);
return [{ json: out }]; // EXACTLY {tone_band, crisis_flag, parse_ok}

const TONE_BANDS = ["gentle","warm-light"];
// <lib:buildContext>
function buildContext(input) {
  const i = input || {};
  // first_name is prospect-controlled text (their own inquiry) that lands inline in the brain's
  // prompt — sanitize the VALUE, not just the key. A tampered name is not a name: reject, never
  // truncate-and-keep. (Nested here, not module-scope, so fn.toString() serialization stays whole.)
  function sanitizeFirstName(raw) {
    if (typeof raw !== 'string') return null;
    const name = raw.trim();
    if (!name || name.length > 40) return null;
    // Unicode letters, single spaces, apostrophes, periods, hyphens. No newlines, digits, or symbols.
    if (!/^[\p{L}][\p{L} '.-]*$/u.test(name)) return null;
    return name;
  }
  // tone_band: coerce/fail-closed to the safest band on any non-enum value.
  const tone_band = TONE_BANDS.includes(i.tone_band) ? i.tone_band : 'gentle';
  // match_tier: only 'exact' or 'none'.
  const match_tier = i.match_tier === 'exact' ? 'exact' : 'none';
  // first_name: ONLY on an exact phone match (disclosure-tier ladder), sanitized, else null.
  const first_name = match_tier === 'exact' ? sanitizeFirstName(i.first_name) : null;
  // faq: string only.
  const faq = typeof i.faq === 'string' ? i.faq : '';
  // Allowlist return — the ONLY four keys. No spread, ever.
  return { tone_band, faq, match_tier, first_name };
}
// </lib:buildContext>
const m = $('LEG2 · Match Resolve').first().json;
const ctx = buildContext({
  tone_band: $('LEG2 · Tone Parse (coerce, fail-closed)').first().json.tone_band, // by-name, not passthrough
  match_tier: m.match_tier,
  first_name: m.first_name,
  faq: $('LEG2 · Inject FAQ').first().json.faq_text,
});
return [{ json: ctx }]; // EXACTLY {tone_band, faq, match_tier, first_name} — no spread, no raw text

// <lib:clinicalGuard>
function clinicalGuard(text) {
  if (!text) return false;
  // Word-boundary aware: "healing" matches, "healthy" does NOT (healthy != heal).
  const banned = /\b(treat|treats|treated|treating|treatment|cure|cures|cured|curing|heal|heals|healed|healing|diagnos[a-z]*|therapy|therapies|therapeutic|patient|patients|prescrib[a-z]*|medical|symptom|symptoms|condition|conditions)\b/i;
  return banned.test(String(text));
}
// </lib:clinicalGuard>
// <lib:numericTokens>
function numericTokens(s) {
  // $ amounts (with optional commas/decimals) and percentages.
  return String(s).match(/\$\s?\d[\d,]*(?:\.\d+)?|\b\d+(?:\.\d+)?\s?%/g) || [];
}
// </lib:numericTokens>
// <lib:numericInFaq>
function numericInFaq(draft, faq) {
  const f = String(faq || '');
  return numericTokens(draft).filter((tok) => {
    const esc = tok.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    // Bounded match: the token must appear in the FAQ NOT as part of a larger number.
    // Catches the substring trap ("30%" inside "130%") and the format trap ("$1,200" vs "$1200").
    const re = new RegExp('(?<!\\d)' + esc + '(?!\\d)');
    return !re.test(f);
  });
}
// </lib:numericInFaq>
const draft = $json.text || '';
const faq = $('LEG2 · buildContext').first().json.faq || '';
if (clinicalGuard(draft)) return [{ json: { route: 'block', reason: 'clinical-language', draft } }];
const offending = numericInFaq(draft, faq);
if (offending.length) return [{ json: { route: 'block', reason: 'numeric-not-in-faq', offending, draft } }];
return [{ json: { route: 'ok', draft } }];

